INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(300, 0, 3, 0, 0, 0, 'Badlands', 'The Badlands are a cracked desert of dry earth, scattered boulders and winding canyons in the southeast of Khaz Modan, reached by a chasm from Loch Modan to the north and a mountain pass from the Searing Gorge to the west. Coyotes, buzzards and restless rock elementals roam the flats, and little else lives easily here. Treasure draws visitors all the same. In the north lie the ruins of Uldaman, a vault left by the titans, and the prospectors of Ironforge and the Explorers'' League who dug at its edges have been slaughtered by Stonevault troggs woken from long slumber and attacked by the Shadowforge clan of Dark Iron dwarves, who hold Angor Fortress. Dustbelcher ogres keep camps scattered across the land, and in Lethlor Ravine in the far east the black dragonflight nests above an ancient prison. At Kargath, the only Horde outpost in Khaz Modan, an expeditionary force sent by the Warchief prepares to carry the war into Blackrock Mountain.', 'warcraft.wiki.gg/wiki/Badlands_(Classic) (cracked desert, access routes, prospectors, Stonevault troggs slaughtered explorers); warcraft.wiki.gg/wiki/Kargath (only Horde outpost in Khaz Modan, Expeditionary Force under Thrall); quests 719, 726, 762, 782, 793 descriptions and reward texts; DB spawns: Shadowforge at Angor Fortress (338), Dustbelcher ogres at 341-344, 347, black whelps at Lethlor Ravine (339); quest 718 description (dwarves fled the Uldaman excavation site)'),
(301, 1, 3, 1, 0, 0, 'Kargath', 'Kargath, named for the Shattered Hand chieftain Kargath Bladefist, stands in the northwest of the Badlands as the only Horde outpost in all of Khaz Modan. Lying so close to the Alliance-held Loch Modan, it is often cut off from Stonard, and its head scout Neeka Bloodscar sends outrunners who do not always arrive. The outpost is the headquarters of the Kargath Expeditionary Force under Warlord Goretooth, whose posted orders call for the death of Dark Iron dwarves on sight. Beside the warriors work the troll Jarkal Mossmeld, an innkeeper and a wind rider master.', 'warcraft.wiki.gg/wiki/Kargath (named after Kargath Bladefist, only Horde outpost in Khaz Modan); quest 1418 description, 1418 reward text (Neeka, outrunner), 1419 description (coyotes steal food); quest 9439 description (Advisor Sarophas, headquarters of the Expeditionary Force, Sunstrider); quests 4081, 4082 (KILL ON SIGHT posters by order of Warlord Goretooth); quest 2338 reward text (I am a troll of my word); DB spawns in area 340: 9077, 6868, 5394, 9356, 2861, 17097, objects 164867, 164868; warcraft.wiki.gg/wiki/Jarkal_Mossmeld (troll in Kargath, no profession given)'),
(302, 1, 3, 2, 0, 0, 'Apocryphan''s Rest', 'South of Kargath, the bones of an enormous dragon lie half sunk in the hardpan, its ribs arching over the sand like the beams of a fallen hall. Nothing else remains of the creature, and the place belongs now to the scavengers. Giant buzzards circle and settle on the old bones, ridge stalkers and elder coyotes hunt the open ground, and lumbering siege golems sometimes stalk past the remains.', 'warcraft.wiki.gg/wiki/Apocryphan''s_Rest (draconic skeleton south of Kargath, flock of hungry buzzards); DB spawns in area 337: Giant Buzzard 2831, Ridge Stalker Patriarch 2734, Elder Crag Coyote 2729, Siege Golem 2749; quest 733 description (stories of siege engines in the Badlands)'),
(303, 1, 3, 3, 0, 0, 'The Dustbowl', 'East of Kargath the ground drops into the Dustbowl, a wide basin of sand where lesser rock elementals tumble about the slopes. Here the gnome scholar Lotwil Veriatus has pitched his camp, choosing the place for its raw materials and its open space, ideal for testing spells that might go wrong. His assistant Lucien Tosselwrench keeps a nervous eye on him, and his mechanical servant Servo rattles off cheerful remarks about the heat. Siege golems trudge past, and a huge carrion bird called Zaricotl circles the basin in search of its next meal.', 'warcraft.wiki.gg/wiki/Badlands_(Classic) (Lotwil''s camp in the Dustbowl); quest 710 description and completion text (raw materials, open space); quest 4062 description (camp to the east of Kargath); creature_text 2920, 2922 (Servo lines about heat); DB spawns in area 1878: 2735, 2921, 2920, 2922, 2749, 2931, object Barrel of Sweet Nectar'),
(304, 1, 3, 4, 0, 0, 'Mirage Flats', 'South of the Dustbowl the land opens into the Mirage Flats, a shimmering plain where heat rising from the dry earth and swirling winds play tricks on the eye and make any trail hard to follow. Elder coyotes, ridge huntresses and rock elementals roam the open sand under circling buzzards. Stranger things pass through as well: the giant Anathemus walks these flats, and the old long distance recovery unit called 7:XT is sometimes seen trundling across them.', 'quest 732 completion text (heat rising from the dry earth and swirling winds make tracking difficult); DB spawns in area 1879: 2729, 2732, 92, 2831, Anathemus 2754, 7:XT 14224; creature_template 2754 (type giant), 14224 subname Long Distance Recovery Unit'),
(305, 1, 3, 5, 0, 0, 'Hammertoe''s Digsite', 'In the north of the Badlands, not far from Uldaman, lies the excavation of the dwarf Hammertoe Grez, who worked with the Explorers'' League seeking the origins of his people among the titan ruins. The Shadowforge clan fell on the site without warning and killed nearly everyone there. Their tunnelers and darkweavers still pick through the abandoned camp, and a crumpled map lies forgotten in the dirt. The few survivors gathered at a small camp just to the south, where Prospector Ryedol plots to recover what was lost.', 'quest 719 description (Shadowforge attack killed nearly everyone, site just north of Ryedol); quest 720 description (Crumpled Map: They''re taking me to Uldaman); quest 723 description (seeking the origins of our people); DB spawns in area 346: Shadowforge Tunneler 2739, Shadowforge Darkweaver 2740, object Crumpled Map 2868; warcraft.wiki.gg/wiki/Hammertoe_Grez'),
(306, 1, 3, 6, 0, 0, 'Angor Fortress', 'Angor Fortress is a Dark Iron stronghold in the northern Badlands, the base from which the Shadowforge clan organizes its digging in Uldaman. Shadowforge warriors and chanters crowd its halls alongside stone golems, and among them dwells Ambassador Infernus, an agent of Ragnaros sent to watch over the hunt for titan artifacts that might be turned against Ironforge. The dwarves have dragged others here too: the goblin Rigglefuzz was once held in the fortress to study power stones from Uldaman, and was thrown out once he had told them their secret.', 'warcraft.wiki.gg/wiki/Angor_Fortress (main site of operations, organize exploration of Uldaman, Infernus agent of Ragnaros); quest 762 description (Infernus sent by Ragnaros to mind the Shadowforge seeking artifacts); quest 726 reward text (Angor Fortress their base of operations); quest 2418 description (Rigglefuzz brought to Angor Fortress to study stones); quest 9439 description (Sarophas robbed, Dark Irons disappeared into Angor Fortress); DB spawns in area 338: 2743, 2742, 2723, 2744, 2745; quest 2418 description (kicked me out of Angor Fortress after I told them the secret)'),
(307, 1, 3, 7, 0, 0, 'The Maker''s Terrace', 'Along the northern edge of the Badlands, close beneath the ruins of Uldaman, the vault of the titans, stretches the Maker''s Terrace. The ground here is rich in ore and herbs, and the Shadowforge clan has claimed it. Surveyors mark out new diggings while Dark Iron diggers and ruffians guard the work, and a hulking war golem patrols the slopes. Among the diggings, carved stone urns of great age lie half buried in the earth.', 'DB spawns in area 1897: Shadowforge Surveyor 4844, Digger 4846, Ruffian 4845, War Golem 2751, Carved Stone Urn 2743, Meeting Stone 178833; warcraft.wiki.gg/wiki/Badlands_(Classic) (Maker''s Terrace rich in minerals and herbs); quest 704 description (ancient urns at the dig site outside Uldaman may have incited the troggs); warcraft.wiki.gg/wiki/Uldaman (titans, makers)'),
(308, 1, 3, 8, 0, 0, 'Valley of Fangs', 'The Valley of Fangs is a small valley between two great stone formations in the heart of the Badlands, its floor prowled by coyotes and cougars. A handful of outcasts have made a camp here. The goblin Rigglefuzz keeps the scavengers off with flash bombs and grills buzzard wings over his fire, Jazzrik sells blacksmithing supplies, and the smith Martek the Exiled works a forge far from anyone who might want him dead. They call themselves a bunch of old, washed-up desert dogs, and few visitors give them reason to say otherwise.', 'warcraft.wiki.gg/wiki/Valley_of_Fangs (small valley between two massive stone formations, camp with Martek, Rigglefuzz, Jazzrik); quests 703, 705 descriptions (buzzard wings, flash bombs to scare wildlife); npc_text 17151 (Martek gossip: old, washed-up desert dogs); quest 1106 reward text (few people who don''t want me dead); DB spawns in area 1877: 4618, 2817, 9179, 2732, 2727'),
(309, 1, 3, 9, 0, 0, 'Camp Kosh', 'Camp Kosh is a Dustbelcher ogre camp in the northeast of the Badlands. When the dwarves fled the Uldaman excavation, they left wagons and crates of supplies abandoned along the way, and the ogres of Kosh fell on them like vultures. Among their spoils is a cart that carried the weapons and stores of Sigrun Ironhew''s camp, leaving the dwarves there without food. Dustbelcher warriors and mystics guard the loot amid the stench of the camp.', 'quest 718 description (abandoned wagons and crates, ogres from Camp Kosh on them like vultures, took the cart, no food); DB spawns in area 341: Dustbelcher Warrior 2906, Mystic 2907, object Excavation Supply Crate 2867; warcraft.wiki.gg/wiki/Dustbelcher (ogres stole the wagons and supplies)'),
(310, 1, 3, 10, 0, 0, 'Camp Boff', 'Camp Boff is one of the Dustbelcher ogre camps that dot the Badlands, southeast of Kargath, where ogres and brutes keep watch while coyotes and ridge huntresses prowl nearby. The nomadic mercenary band of Boss Tho''grun, which drifts between the ogre camps and is hard to track across the shimmering desert, is said to pass through here at times. Since the band betrayed the Horde, both Horde and Alliance have sent hunters here after the stolen relic it carries.', 'quest 782 description and completion text (Camp Boff southeast of Kargath, Tho''grun betrayed the Horde); quest 732 description and completion text (band of wandering ogres sometimes seen near Camp Boff, nomadic); warcraft.wiki.gg/wiki/Dustbelcher (nomadic band traveling between the camps); DB spawns in area 342: Dustbelcher Ogre 2701, Brute 2715, Feral Crag Coyote 2728'),
(311, 1, 3, 11, 0, 0, 'Camp Cagg', 'Camp Cagg sits in the southwestern Badlands, among broken hills where greater rock elementals grind across the slopes and the massive elemental Rumbler is said to roam. Dustbelcher maulers, shamans and wyrmhunters make their camp here beside the living stone, and the scholar Lotwil Veriatus has scried the elementals near them for the bracers of rock binding they carry. The camp lies on the circuit of Boss Tho''grun''s wandering mercenaries, who drift from one ogre camp to the next.', 'DB spawns in area 344: Dustbelcher Mauler 2717, Shaman 2718, Wyrmhunter 2716, Greater Rock Elemental 2736, Rumbler 2752, Boss Tho''grun 2944; quest 712 description (greater rock elementals southwest, near some ogres)'),
(312, 1, 3, 12, 0, 0, 'Dustbelch Grotto', 'Dustbelch Grotto, a cave in the far southwest of the Badlands, is the main home of the Dustbelcher ogres. Ogre lords hold court here among ogre mages, maulers and shamans, and greater rock elementals lumber about the entrance. The ogres who once fought for the Horde are part of it no longer, and those of the grotto go well supplied with scrap metal. Dwarves short of materials eye the metal plates and parts the ogres carry, whispering that the old tales of siege engines in the Badlands may hold some truth.', 'quest 733 description (main ogre camp at Dustbelch Grotto, ogres well equipped with scrap metal, stories of siege engines); quest 782 completion text (ogres are part of the Horde no longer); warcraft.wiki.gg/wiki/Dustbelcher (mostly found in Dustbelch Grotto); DB spawns in area 347: 2719, 2720, 2717, 2718, 2736'),
(313, 1, 3, 13, 0, 0, 'Agmond''s End', 'In the south of the Badlands, past Angor Fortress, lies the smallest of the Ironforge excavations, a tiny operation where Prospector Agmond, who had charge of the dwarven digs in these lands, was last known to be working. Word from him stopped coming weeks ago. Stonevault troggs now hold the site, bonesnappers and shamans among them, and a trogg called Murdaloc lurks in their midst. Close by, the mad hermit Theldurin the Lost has made his camp.', 'quest 738 description (southernmost dig site, tiny operation past the Angor Fortress); quest 738 reward text (skeleton, bones picked clean), quest 739 description (crawled from the west, Murdaloc scrawled); warcraft.wiki.gg/wiki/Agmond''s_End (troggs infested the site, Theldurin camp nearby); DB spawns in area 345: Stonevault Bonesnapper 2893, Shaman 2894, Murdaloc 2945, Theldurin 2785, object Battered Dwarven Skeleton 2875; quest 739 log text (Slay Agmond''s killer, Murdaloc)'),
(314, 1, 3, 14, 0, 0, 'Dustwind Gulch', 'Dustwind Gulch is a wind-scoured cut in the eastern Badlands, where rabid coyotes and ridge stalkers hunt and starving buzzards wait for what they leave behind. At its edge a rear passage opens into Uldaman, and Stonevault troggs, roused from long slumber within the ruins, prowl the gulch, their seers and bashers among them. Some carry flakes of indurium, a metal rumored to resist heat and stress, whose true ore lies only deep within Uldaman.', 'areatrigger 902 Uldaman Exit at -6606,-3762, posarea gives 1898; DB spawns in area 1898: Stonevault Seer 2892, Basher 6733, Rabid Crag Coyote 2730, Ridge Stalker 2731, Starving Buzzard 2829; quest 1108 description (Stonevault troggs carry indurium flakes, rumored resistance to heat and stress, true ore deep in Uldaman); warcraft.wiki.gg/wiki/Uldaman (troggs woke and slaughtered the explorers)'),
(315, 1, 3, 15, 0, 0, 'Lethlor Ravine', 'In the far east of the Badlands a deep ravine cuts through the mountains, and it belongs to the black dragonflight. Scalding whelps swarm its floor and scorched guardian drakes keep watch over it. The ravine holds an older secret: the Seal of the Earth, a prison held shut by runestones set in three pillars of amethyst, opal and diamond, which only the Sign of the Earth can draw out. Near the mouth of the ravine Thorkaf Dragoneye teaches the working of dragon scale, and warns his visitors that their stench will draw every dragon for miles.', 'quest 717 and 793 descriptions (Seal, runestones, Pillars of Amethyst, Opal and Diamond); quest 732 reward text (Sign of the Earth created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing''s lieutenants, the twins); quest 717 description (black dragons have taken up residence); warcraft.wiki.gg/wiki/Lethlor_Ravine (black whelps and drakes); DB spawns in area 339: Scalding Whelp 2725, Scorched Guardian 2726, objects 2933, 2842, 2848, 2858; npc_text 3802 (Thorkaf), quest 5145, Thorkaf 7867 at -6841,-3638'),
(316, 2, 3, 1, 1, 0, 'Hammertoe Grez', 'Hammertoe Grez, a dwarven prospector of Ironforge, worked with Historian Karnik to uncover the lost artifacts of Uldaman. He searched the titan ruins for the origins of his people, and for the old magics that give life to golems, hoping to find them before the Dark Iron dwarves could. When the Shadowforge clan overran his digsite, they carried him off to Uldaman to wring from him what he knew. Those who reach him in the ruins find him beaten and coughing, begging them to win back his amulet from Magregan Deepshadow before it leads the Shadowforge to scrolls for ever more powerful golems.', 'quest 724 description (Hammertoe and Karnik working together to find the lost artifacts in Uldaman); quest 721 description (golem magics, Hammertoe searching to stop them, held to learn what he knows); quest 723 description (seeking the origins of our people), 723 reward text (amulet was his life''s work); quest 722 description and texts; warcraft.wiki.gg/wiki/Hammertoe_Grez'),
(317, 2, 3, 2, 1, 0, 'Prospector Ryedol', 'Prospector Ryedol of the Explorers'' League worked under Hammertoe Grez at the dig north of his camp and barely escaped with his life when the Shadowforge attacked and killed nearly everyone there, and he counts his boss among the dead. Now he waits with a few survivors at a small camp south of the site, mourning Hammertoe and scheming to recover the camp''s supplies, above all his lucky pick. He cannot say what the Dark Irons were looking for, only that they plainly had a purpose.', 'quest 719 description (boss Hammertoe, barely escaped, lucky pick); quests 720 reward text, 721 description; quest 723 reward text (can''t let his death be in vain); creature_template 2910 subname Explorers'' League; quest 719 completion text (Not sure what the Shadowforge were lookin'' for, but they definitely had a purpose)'),
(318, 2, 3, 3, 0, 0, 'Ambassador Infernus', 'Ambassador Infernus is a creature of living fire, sent by Ragnaros himself to Angor Fortress to keep watch over the Shadowforge clan as it hunts for lost artifacts in Uldaman. The Dark Iron dwarves serve the Firelord, and the ambassador makes sure their discoveries serve him too. Under his eye the Shadowforge have caused heavy losses among the dwarves of Ironforge, and the advisors of King Magni fear what weapons the artifacts might yield. The king''s council has ordered him destroyed.', 'quest 762 description (sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts, tremendous casualties); quest 762 reward text (in the name of King Bronzebeard); creature_template 2745 type 4 (elemental), faction 54; warcraft.wiki.gg/wiki/Angor_Fortress (agent of Ragnaros); warcraft.wiki.gg/wiki/Ambassador_Infernus (fire elemental)'),
(319, 2, 3, 4, 0, 0, 'Lotwil Veriatus', 'Lotwil Veriatus is a gnome of Kharanos and a scholar of renown in the elemental sciences, who has set up camp in the Dustbowl to perfect his shackles of elemental binding. With them, he believes, mages will command elementals far mightier than any summoned before, a perfect blend of alchemy, engineering and the arcane. He is brilliant, absent-minded and forever muttering to himself, and his assistant Lucien prefers to watch from behind cover.', 'quest 710 description (shackles of elemental binding), 778 description (perfect blend of alchemy, engineering, and the arcane); quest 714 description (Kharanos), 712 completion text; quest 4062 description (scholar of some renown in the field of elemental sciences); quest 4063 description (killed Argelmach ten years ago, twisting my life''s work); quest 777 description (Lucien: over here behind cover), 710 reward text (mumbling); warcraft.wiki.gg/wiki/Lotwil_Veriatus (born in Kharanos, absent-minded); warcraft.wiki.gg/wiki/Lotwil_Veriatus (gnome, born in Kharanos, killed Argelmach)'),
(320, 2, 3, 5, 0, 0, 'Theldurin the Lost', 'Theldurin the Lost was once a member of the Twilight''s Hammer, until he lost his mind and turned against the cult''s teachings. Before he fled, he stole a scroll his former brethren prize, and they want it back. Now he lives in a lonely camp in the southern Badlands, gibbering to himself, confessing that being crazy is sometimes his only solace. He fears an approaching doom, dares not utter the names of those who bring it, and hunts for any lore that might show how to foil them.', 'quest 687 description (once a member, lost his mind, scorned teachings, stole the scroll, hides in Badlands gibbering and mad); quest 709 description (doom approaching, cannot utter their names); quest 737 reward text (if THEY are freed); quest 692 description (scroll can pull Myzrael to the surface); DB spawn 2785 in area 345; warcraft.wiki.gg/wiki/Theldurin_the_Lost; quest 687 reward text (sometimes being crazy is my only solace); quest 709 description (a doom approaching, cannot utter their names, learn how to foil them)'),
(321, 2, 3, 6, 0, 0, 'Garek', 'Garek is a quiet agent of the Kirin Tor, sent to the Badlands by his master Krasus to put an end to the trouble brewing in Lethlor Ravine. He keeps the exact nature of his task to himself, saying only that it is of vital importance, and waits at a lonely camp in the eastern Badlands, where word of willing helpers reaches him from the stranded dwarves of Sigrun Ironhew. First he needs the Sign of the Earth, stolen by a band of wandering ogres, and only once it is in his hands will he say more.', 'quest 732 description (sent by my master Krasus of the Kirin Tor, cannot divulge the nature of my assignment); quest 717 description and reward text (cannot ensure they remain imprisoned, Kirin Tor need not worry, Krasus pleased); DB spawn 2888 at -6789,-3619; quest 732 description (heard from Sigrun, vital importance, ogres stole the Sign, bring it and I will tell you more)'),
(322, 2, 3, 7, 2, 0, 'Warlord Goretooth', 'Warlord Goretooth commands the Kargath Expeditionary Force, the army sent by the Warchief to Khaz Modan to strike at the renegade Blackrock orcs and their Dark Iron allies in Blackrock Mountain. From his post at Kargath he issues bounties on the servants of the Dark Iron general Angerforge, whose forces slaughtered the 109th division of the Expeditionary Force, and orders the destruction of the masters of Blackrock Spire. He is a hard commander who tells his soldiers to move on from their losses and focus on the task at hand.', 'quests 4081, 4082, 4132 descriptions (109th division, Angerforge); quest 4903 description (inhabitants of Blackrock Spire must be destroyed); quest 3821 description (Goretooth tells Thal''trak to move on and focus on the task at hand); warcraft.wiki.gg/wiki/Kargath_Expeditionary_Force (sent by Thrall, Rend Blackhand); creature_template 9077 faction 83 (Horde)'),
(323, 2, 3, 8, 0, 0, 'Martek the Exiled', 'Martek the Exiled is a smith who knows more about metal than almost anyone, living in the Valley of Fangs among a few fellow outcasts. Strangers who find him are greeted with suspicion: he assumes they have come about an axe he once forged for the Blackrock chieftain Gath''Ilzogg, or to avenge the honor of a certain Duchess Pamay, and he would rather fight than explain. Fizzle Brassbolts of the Shimmering Flats and his brother are among the few people who do not want him dead. Nor is he out here only to avoid people: the Badlands hold indurium, a metal rumored to resist heat and stress.', 'quest 1106 description (great smith, knows more about metal than anyone), completion text (Gath''Ilzogg axe, Duchess Pamay), reward text (Fizzle and his brother); quest 1108 reward text, 1137 description (indurium heat test); warcraft.wiki.gg/wiki/Martek_the_Exiled (Gath''Ilzogg is a Blackrock leader in Redridge); quest 1108 description (not out here just to stay away from people, indurium rumored to resist heat and stress)'),
(324, 2, 3, 9, 0, 0, 'Blacklash and Hematus', 'Blacklash and Hematus are twin black drakes, lieutenants of Deathwing, and allies of the Horde in the Second War, when the orcs fought alongside the Black Dragon. Few dragons fought as ferociously as these two. The Dark Iron dwarves of Angor Fortress forged the Sign of the Earth to bind them, and they were sealed in a prison in Lethlor Ravine, held by three runestones. Now the black dragonflight gathers around their prison, and those who fear their release mean to free them only to see them dead.', 'quest 782 description (Horde''s alliance with Deathwing during the Second War, two of his lieutenants imprisoned in Lethlor Ravine); quest 732 reward text (Sign created by Dark Irons of Angor Fortress to bind two of Deathwing''s lieutenants, the twins); quest 793 completion text (few dragons fought as ferociously); quest 717 description, 782 reward text (free them to their doom); smart_scripts 293300 (Seal of the Earth summons 2757 and 2759)'),
(325, 2, 3, 10, 0, 0, 'Boss Tho''grun', 'Boss Tho''grun leads a band of Dustbelcher ogre mercenaries that wanders between the ogre camps of the Badlands. The Horde of Kargath hired him to help obtain the Sign of the Earth, the key to the drake prison in Lethlor Ravine. Once the Sign was in reach, Tho''grun turned on his employers, overwhelmed them and kept it for himself. His treachery has made him a target for Horde and Alliance alike, both of whom want the Sign he carries.', 'quest 782 description and completion text; quest 732 description (wandering ogres stole the Sign); warcraft.wiki.gg/wiki/Dustbelcher (nomadic band, both factions after him); creature_loot 2944 drops Sign of the Earth'),
(326, 3, 3, 1, 1, 0, 'Hammertoe and the Shadowforge', 'The Shadowforge clan of the Dark Iron dwarves fell without warning on Hammertoe''s Digsite in the north of the Badlands and killed nearly everyone there. Prospector Ryedol of the Explorers'' League barely escaped, and from a small camp just to the south he mourns his master, Hammertoe Grez, whom he believes slain with the rest. He cannot say what the attackers were looking for, only that they plainly had a purpose. The camp''s supplies lie scattered among the Shadowforge who still pick through the site, and Ryedol wants them back, his lucky pick above all. In the dirt of the abandoned dig lies a crumpled map.', 'quests 719, 720, 721, 722, 723, 724 descriptions and reward texts'),
(327, 3, 3, 2, 0, 0, 'The Prisoners of Lethlor', 'Deep in Lethlor Ravine lies the Seal of the Earth, a prison, and its key is the Sign of the Earth. Two very different hunters want that key. At Kargath, Gorn wants the prisoners, old allies of the Horde from the Second War, silenced to restore its honor, and had hired Boss Tho''grun''s ogre mercenaries to win the Sign, only to be betrayed and robbed of it. For the Alliance, the Kirin Tor agent Garek came on the orders of Krasus and keeps his purpose to himself, finding helpers through the stranded dwarves of Sigrun Ironhew''s camp. Both want the Sign taken from Tho''grun''s wandering band.', 'quests 782, 793 descriptions, completion and reward texts; quests 718, 732, 717 descriptions and reward texts; quests 779, 795 texts (Seal broken)'),
(328, 3, 3, 3, 0, 0, 'Lotwil''s Shackles', 'In the Dustbowl, Lotwil Veriatus has set out to build shackles of elemental binding strong enough to master an elemental mightier than any summoned before. He tests his spells on shards of the local rock elementals, then on great slabs and on the very bracers that bind the greater elementals. Frost oil, which a goblin friend of his in Alterac can teach others to make, will cool the shackles and hold their enchantments, enough, he hopes, to stop the summoned creature from killing everyone, and a gyrochronatom will complete them. One last part waits with his assistant Lucien: cog number five, which Lucien hands over before taking cover.', 'quests 710, 711, 712, 713, 714, 734, 777, 778 descriptions and texts; quest 713 description (Frost Oil, goblin friend in Alterac, stop our summoned friend from killing us all)'),
(329, 3, 3, 4, 2, 0, 'The Rise of the Machines', 'Scouts of the Kargath Expeditionary Force met strange machines during their first forays into the Searing Gorge, and traced them back to the Burning Steppes, perhaps to Blackrock Depths itself. From her post at Kargath, Hierophant Theodora Mulvadania means to learn where they come from. She asks for shards taken from the rock automatons and lesser rock creations of the Steppes, so that she can study them and determine their source of origin, and warns that the task is not to be taken lightly.', 'quests 4061, 4062, 4063 descriptions and reward texts; creature_template 9079 (Kargath Expeditionary Force, area 340)'),
(330, 3, 3, 5, 0, 0, 'The Scroll of Myzrael', 'Theldurin the Lost fled the Twilight''s Hammer with a stolen scroll, and the cult wants it back. Its members send seekers to the Badlands to find him, a gibbering hermit camped in the south who greets visitors with crazy talk. He has errands of his own for anyone who will listen. A doom is approaching, he says, though he cannot utter the names of those behind it, and if more can be learned of them, perhaps they can be foiled. For that he wants the Tablet of Ryun''eh, hidden deep in Uldaman in a chest crafted before the works of any dwarf.', 'quests 687, 692, 656 descriptions and texts; quests 709, 727, 728, 735, 736, 737 descriptions and texts; warcraft.wiki.gg/wiki/Theldurin_the_Lost'),
(331, 3, 3, 6, 1, 0, 'Agmond''s Fate', 'Prospector Agmond had charge of the dwarven excavations in the Badlands, and for weeks Prospector Ironband, at his own dig in Loch Modan, has heard nothing from him. Ironband needs Agmond''s report, and the long silence already has him speaking of Agmond''s charge in the past tense. Word last placed Agmond at the southernmost of the Badlands sites, a tiny operation past Angor Fortress, and Ironband, sent help by Prospector Stormpike of Ironforge, wants someone to go there, find him and learn what became of him.', 'quests 707, 738, 739, 704 descriptions and reward texts; quest 707 description (Stormpike: Ironband needs legwork on another of our excavations); quest 738 description (I say was because I haven''t heard from him in weeks)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(301, 1, 8, 255, 'Since the blood elves joined the Horde, Kargath has gained a guest from distant Quel''Thalas. Advisor Sarophas came expecting a settlement worthy of the Expeditionary Force''s headquarters and found what he calls a hovel of uncouth, sniggering savages, who only laughed at him when he told them how Dark Iron dwarves had robbed him.', 'quest 9439 description and completion text (Sarophas, headquarters of the Expeditionary Force, For Sunstrider''s sake); creature_template 17097 Advisor Sarophas, faction 1604 (Silvermoon); warcraft.wiki.gg/wiki/Advisor_Sarophas (blood elf, added in The Burning Crusade)'),
(305, 1, 0, 255, 'The crumpled map carries a message roughly chalked by Hammertoe himself. The Shadowforge did not kill him with the rest: they dragged him away, and he was being taken to Uldaman. Beneath, he begged Ryedol to send help.', 'quest 720 description (map text: They''re taking me to Uldaman. Send help.); gameobject 2868 Crumpled Map starts 720'),
(306, 1, 8, 255, 'Lately the fortress has swallowed loot as well as prisoners. Advisor Sarophas, a blood elf newly come to the Horde''s outpost at Kargath, was robbed by Dark Iron dwarves who then vanished behind these walls, and his pack and rapier lie stowed somewhere within.', 'quest 9439 description and log text (robbed, disappeared into the Angor Fortress, Advisor''s Pack and Advisor''s Rapier in their holding places there)'),
(307, 1, 0, 255, 'The urns were unearthed by the diggers of Prospector Agmond at this site outside Uldaman, and his last report to Loch Modan spoke of them. Prospector Ironband fears that they stirred the troggs to fury, just as the idols found at his own dig did, and he wants them gathered for study.', 'quest 704 description (Agmond''s last report, ancient urns at the dig site outside Uldaman, incited the troggs as did the idols)'),
(313, 1, 0, 255, 'Agmond never left the desert. His broken skeleton was found here, its bones picked clean, at the end of a trail of bloody smears across rock and sand where he had crawled from the west. Beside his dead hand a single name was scratched into the sandstone: Murdaloc.', 'quest 738 reward text (skeleton, bones picked clean); quest 739 description (tracks from the west, crawled, Murdaloc scrawled beside his hand)'),
(315, 1, 0, 255, 'The prisoners beneath the Seal are Blacklash and Hematus, black drakes and two of Deathwing''s lieutenants, remembered by the Horde from its alliance with him in the Second War. The Sign of the Earth is the key to their prison, and black dragons of their old master''s flight now gather in the ravine above them.', 'quest 782 description (Horde''s alliance with Deathwing in the Second War, two of his lieutenants Blacklash and Hematus imprisoned within Lethlor Ravine, Sign a key to the drakes'' prison); DB spawns in area 339: Scalding Whelp 2725, Scorched Guardian 2726'),
(315, 2, 0, 255, 'Garek knew the Sign''s history. The Dark Iron dwarves of Angor Fortress made it to bind two of Deathwing''s ruthless lieutenants, the twin drakes Blacklash and Hematus, and they are the prisoners beneath the Seal. Now black dragons of their old master''s flight gather in the ravine above them.', 'quest 732 reward text (Sign created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing''s ruthless lieutenants, the twins Blacklash and Hematus); quest 717 description (black dragons have taken up residence; offered on the turn-in of 732)'),
(316, 1, 0, 255, 'The amulet came back to him. Holding his wounds, Hammertoe begged his rescuers to take it to Prospector Ryedol, who knew both his search for the origins of their people and his mission to stop the Shadowforge. He did not live to see what came of it: when the amulet, his life''s work, reached Ryedol, it came with the certainty that Hammertoe was dead.', 'quest 722 reward text, 723 description (take the amulet to Ryedol; he knows I was seeking the origins of our people and stopping the Shadowforge); quest 723 reward text (knowing for sure, his life''s work, his death)'),
(317, 1, 0, 255, 'A crumpled map from the digsite changed everything. In Hammertoe''s own chalk scrawl it said that he was being taken to Uldaman, and Ryedol could hardly believe it. He pleaded for someone to reach his boss before the Shadowforge learned all he knew about the titan excavations, for then all of Ironforge could be in trouble.', 'quest 720 description and reward text (Hammertoe''s alive?!); quest 721 description (holding him hostage, all of Ironforge in huge trouble)'),
(317, 2, 0, 255, 'Hammertoe''s amulet came back to him instead. His spirits had been higher, Ryedol admitted, when he thought Hammertoe dead, for knowing it for certain only made the pain worse. The amulet was his boss''s life''s work, and swearing that the death would not be in vain, he resolved to send it on to Historian Karnik in Ironforge, who had shared Hammertoe''s search.', 'quest 723 reward text; quest 724 description (Karnik and Hammertoe working together)'),
(319, 1, 0, 255, 'Lotwil has a darker past than his mutterings suggest. Ten years ago he killed Argelmach, a despicable dwarf bent on twisting Lotwil''s life''s work to his own diabolical ends. When shards etched with the initials G.L.A. were brought to him from the golems of the Burning Steppes, the gnome went white: he knew those markings.', 'quest 4062 description (G.L.A.) and reward text (Lotwil''s face turns white); quest 4063 description (killed Argelmach ten years ago, twisting my life''s work)'),
(320, 1, 0, 255, 'The stolen scroll is the Scroll of Myzrael, by which the cult hoped to bring back the one it calls the Lady. Theldurin dreads it, for its magic can pull Myzrael to the surface world. Yet if she is already free and only gathering strength, he reasons, the scroll will be needed to trap her again, and enraged elementals have torn it to pieces.', 'quest 687 description (scroll of Myzrael, to bring the Lady back to us); quest 692 description (pull Myzrael to the surface, maybe she already is free, elementals tore it up)'),
(320, 2, 0, 255, 'His deepest dread lies elsewhere. With a tablet from Uldaman and Yagyin''s Digest, a book his old brethren keep and study, Theldurin seeks a way to foil the doom he will not name. The digest gives him hope, and a greater fear: if they are ever freed and rise to the surface, he says, the world is worm food.', 'quests 709, 727, 728 descriptions; quest 737 reward text (if THEY are freed and rise to the surface, we''re all worm food)'),
(321, 1, 0, 255, 'With the Sign recovered, Garek revealed his purpose. The Dark Iron dwarves of Angor Fortress had made the Sign to bind two of Deathwing''s lieutenants, the twins Blacklash and Hematus. Now black dragons had taken up residence around their prison and ogres had stolen its key: no one could ensure the twins would stay imprisoned. Rather than trust the Seal of the Earth any longer, they would be freed, and slain.', 'quest 732 reward text (Sign made by the Dark Irons of Angor Fortress to bind the twins Blacklash and Hematus); quest 717 description (offered on the turn-in of 732)'),
(321, 2, 0, 255, 'The drakes are dead, and their bindings and the Sign came back to Garek. No longer, he says, will the Kirin Tor need to worry over the prisoners of Lethlor, and he means to return and report his success to Krasus, who will no doubt be pleased.', 'quest 717 reward text and log text (return the bindings and the Sign)'),
(323, 1, 0, 255, 'Martek put the rumor to the test. He put indurium flakes, taken from the Stonevault troggs, into the heat of his forge, and they held. Indurium has an amazing resistance to heat, he declared, though true indurium ore must be mined deep within Uldaman, and he sent word of it to Fizzle.', 'quest 1108 description and reward text; quest 1137 description (amazing resistance to heat, true ore deep within Uldaman)'),
(326, 1, 0, 255, 'The map bore Hammertoe''s chalk scrawl: he was alive, and being taken to Uldaman. Ryedol pleaded for someone to find him. The Dark Irons had long sought magics to build more powerful golems, as Hammertoe had, though only to stop them, and they would keep him alive just until they learned what he knew.', 'quest 720 description and reward text; quest 721 description'),
(326, 2, 0, 255, 'Rescuers found the old prospector in the ruins of Uldaman, beaten, weak and coughing, but alive. With what strength he had he asked for his amulet. Magregan Deepshadow had taken it, and it could lead the Shadowforge straight to scrolls that would surely let them create even more powerful golems.', 'quest 721 reward text; quest 722 description'),
(326, 3, 0, 255, 'Once the amulet was won back, Hammertoe sent it to Ryedol, but he did not survive, and the amulet reached Ryedol with the certainty of his death. Ryedol swore that the death would not be in vain and resolved to send the amulet on to Historian Karnik in Ironforge, who had shared Hammertoe''s search and would know what must be done. The blow Ironforge struck in answer belongs to the historian''s own tale.', 'quests 722, 723 reward texts; quest 724 description (offered on 723''s turn-in)'),
(327, 1, 0, 255, 'The prisoners are Blacklash and Hematus, black drakes and two of Deathwing''s lieutenants, the very allies of old whom Gorn would silence. Black dragons now gather in the ravine around their prison, and its only key has already been stolen once.', 'quest 782 description (Blacklash and Hematus, two of Deathwing''s lieutenants, depraved allies of old); quest 793 description (the ravine is home to countless drakes)'),
(327, 2, 0, 255, 'With the Sign in hand, Garek told what it was. The Dark Iron dwarves of Angor Fortress made it to bind two of Deathwing''s ruthless lieutenants, the twins Blacklash and Hematus. Black dragons now gather in the ravine around their prison, and its only key has already been stolen once.', 'quest 732 reward text; quest 717 description (black dragons have taken up residence; offered on 732''s turn-in)'),
(327, 3, 0, 255, 'Once the Sign was taken from Tho''grun, the course was set: the drakes would be freed, only to meet their doom. With the Sign, the three runestones could be drawn from the Pillars of Amethyst, Opal and Diamond, and set into the Seal to break it.', 'quest 782 reward text (Tho''grun dead, free them to their doom); quest 793 description; quest 717 description'),
(327, 4, 0, 255, 'The runestones were set into their recesses, and a violent rumbling shook the earth as the Seal of the Earth was broken. Blacklash and Hematus rose from their prison, and died at the hands of those who had freed them, their bindings carried back with the Sign as proof.', 'quests 779, 795 reward texts (Seal broken); smart_scripts 293300 (the Seal summons 2757 and 2759); quests 793, 717 log texts (slay them, return the bindings and the Sign)'),
(328, 1, 0, 255, 'At last the shackles were done. Calling on Lucien and Servo to bear witness to the perfect blend of alchemy, engineering and the arcane, Lotwil declared a groundbreaking day and summoned forth a powerful elemental, the Fam''retor Guardian. It broke free of his control at once, and the shackles went with it.', 'quest 778 description and log text (summon a powerful elemental; defeat the Fam''retor Guardian and bring the shackles back); smart_scripts 2921 and 292100 (on accepting 778 Lotwil casts his summoning and summons 2919)'),
(328, 2, 0, 255, 'Only after the guardian was beaten down could the shackles be recovered. Lotwil, unsure what could have gone wrong, used his magics to send the creature back to its home plane, called the whole affair quite an ordeal, and admitted that it was not quite the outcome he had expected.', 'quest 778 completion and reward text'),
(329, 1, 0, 255, 'Under an enormous monocle, Theodora found initials etched into the foundation of every shard: G.L.A., with a rank marking beneath, Rank IV on the creations destroyed in the Steppes, which she took for a lowly rank. She sent a sample east to Lotwil Veriatus in the Dustbowl, a scholar of some renown in the elemental sciences.', 'quest 4061 reward text; quest 4062 description'),
(329, 2, 0, 255, 'Lotwil''s face turned white. The markings belonged to Argelmach, a despicable dwarf bent on twisting Lotwil''s life''s work to his own ends, whom the gnome himself had killed ten years before. If this was Argelmach''s handiwork he must be destroyed, so Lotwil asked for the golem lord''s head and the cores of the golems guarding him in Blackrock Depths.', 'quest 4062 reward text; quest 4063 description and log text'),
(329, 3, 0, 255, 'The head proved to be no flesh at all, but a creation of dark iron: a shadow of Argelmach, another machine. Lotwil fears that its destruction will be short lived, and that another will soon rise to take its place.', 'quest 4063 reward text'),
(330, 1, 0, 255, 'The scroll is the Scroll of Myzrael, and Theldurin no longer has it. Its magic can pull Myzrael to the surface world, he warns, yet if she is already free and only gathering strength, it will be needed to trap her again. Enraged elementals stole it and tore it apart, and now they fight over the fragments.', 'quest 692 description'),
(330, 2, 0, 255, 'The torn, crumpled and singed fragments were won back from the elementals. Calling them perhaps the only chance against the evil of Myzrael, Theldurin went hunting for his scrap-ratchet to fix the pieces back together, his thoughts on trapping her again before it is too late.', 'quest 692 completion and reward text'),
(330, 3, 0, 255, 'The tablet told much, but not nearly enough. Theldurin wants Yagyin''s Digest, written ages past, which the people he fled keep in many places for their most learned to study. Bearing his Sigil of the Hammer, a seeker could pass as one of them before a keeper of the cult hidden in one of the great cities, and ask for a copy.', 'quest 709 reward text; quests 727, 728 descriptions'),
(330, 4, 0, 255, 'The digest was won at the price of three relics, the star, the hand and the heart, from a keeper who warned that the truth can burn. Theldurin received it with glimmering hope: it may yet save everyone. Unless, he added, they are freed and rise to the surface, and then all are worm food.', 'quests 735, 736 titles and texts; quest 737 description and reward text'),
(331, 1, 0, 255, 'The search ended in the southern desert. There, alone in the open, lay a battered dwarven skeleton, broken, its bones picked clean by the scavengers of the Badlands: all that remained of Prospector Agmond.', 'quest 738 reward text'),
(331, 2, 0, 255, 'His tracks told how he died. Bloody smears across rock and sand showed that he had crawled a long way from the west, and beside his dead hand a single name was scrawled in the sandstone: Murdaloc. The trogg who bore it, and the Stonevault bonesnappers around him, would answer for the deed.', 'quest 739 description and log text'),
(331, 3, 0, 255, 'Murdaloc and his bonesnappers paid for it. Ironband took the news soberly, but Agmond had a strong arm, a fierce hammer swing and a skull as thick as they come, and Ironband is sure the old prospector took a great many troggs down with him.', 'quest 739 reward text'),
(331, 4, 0, 255, 'Agmond''s last report troubles Ironband more now that he is dead. It spoke of ancient urns his diggers had uncovered at the dig site outside Uldaman, and Ironband fears those urns roused the troggs just as the idols found at his own site did. He wants them gathered and brought to him for study.', 'quest 704 description'),
(331, 5, 0, 255, 'The urns came back to Loch Modan. With luck and diligence, Ironband hopes, the League will find whatever link exists between the troggs and these ancient artifacts, and he promises that the efforts of those who helped will not be forgotten. And neither, he adds, will Agmond.', 'quest 704 reward text');
